#ifndef PATROL_SUPERVISOR_WORKER_H
#define PATROL_SUPERVISOR_WORKER_H

#include "common/protocol.h"

#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

#define PATROL_MAX_WORKERS 32

typedef enum {
  WORKER_EMPTY = 0,
  WORKER_RUNNING,
  WORKER_STOPPING,
  WORKER_EXITED
} WorkerPhase;

typedef struct {
  int id;
  char name[64];
  char mode[32];
  pid_t pid;
  pid_t process_group;
  int report_fd;
  WorkerPhase phase;
  int exit_code;
  int term_signal;
  int timed_out;
  int report_received;
