#ifndef PATROL_PROTOCOL_H
#define PATROL_PROTOCOL_H

#include <stddef.h>
#include <stdint.h>

#define PATROL_FRAME_MAX_PAYLOAD 1024U
#define PATROL_FRAME_BUFFER_CAPACITY 4096U

typedef struct {
  uint8_t status;
  char worker[64];
  char message[512];
} PatrolReport;

typedef struct {
  uint8_t bytes[PATROL_FRAME_BUFFER_CAPACITY];
