      if (*argv[index] == '\0' || *end != '\0' || value < 0 || value > INT_MAX) {
        usage(argv[0]);
        return 64;
      }
      report_fd = (int)value;
    } else {
      usage(argv[0]);
      return 64;
    }
  }
  if (name == NULL || mode == NULL || report_fd < 0 || strlen(name) >= sizeof(((PatrolReport *)0)->worker)) {
    usage(argv[0]);
    return 64;
  }
  CheckResult check;
  if (checks_run(mode, &check) != 0) {
    perror("checks_run");
    return 65;
  }
