  if (strcmp(verb, "status") == 0) {
    struct timespec delay = {.tv_sec = 0, .tv_nsec = 100000000};
    nanosleep(&delay, NULL);
    char text[32768];
    if (fs_read_text(snapshot, text, sizeof(text)) < 0) {
      perror("read state");
      return 74;
    }
    fputs(text, stdout);
  }
  return 0;
}

