    errno = EINVAL;
    return -1;
  }
  if (set_limit(RLIMIT_CPU, profile->cpu_seconds) != 0) return -1;
#ifdef RLIMIT_AS
  if (set_limit(RLIMIT_AS, profile->address_space_bytes) != 0) return -1;
#endif
  if (set_limit(RLIMIT_NOFILE, profile->open_files) != 0) return -1;
  return 0;
}

